// Runtime subsets for existing application distributions. Destinations retain
// their published URLs; every generated byte comes from the canonical tree.
import {cp, mkdir} from 'node:fs/promises';
import {dirname, join, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import {checkRuntimeArtifacts, listRuntimeArtifactFiles} from './runtime_artifacts.mjs';

const repositoryRoot = fileURLToPath(new URL('../', import.meta.url));
const ids = value => Object.freeze(value.split(' '));
export const runtimeArtifactProfiles = Object.freeze({
  full: ids('sid ay8910 gameboy_apu huc6280 wonderswan pokey k051649 nesapu pwm32x nuked_opn2 okim6258 rf5c164 segapcm segapsg spc y8950 ym2151 ym2203 ym2413 ym2608 ym2610b ym2612 ym3438 ym3526 ym3812 ymf262 ymf276 ymf278b ymf288 cdda msm5205 ps1_spu scsp dx7 native_audio_effect'),
  playground: ids('sid nesapu pwm32x ay8910 ym2413 ym3526 ym3812 y8950 ymf262 ps1_spu scsp spc ym2151 gameboy_apu huc6280 pokey wonderswan okim6258 rf5c164 ym2612 nuked_opn2 segapsg ym2203 ym2608 ym2610b cdda msm5205 dx7 native_audio_effect'),
  analyzer: ids('nesapu pwm32x spc huc6280 wonderswan pokey okim6258 ym2610b ay8910 k051649 segapcm gameboy_apu y8950 ymf278b ym3526 ym3812 ymf262 ym2151 ym2413 ym2203 ym2608 ym2612 nuked_opn2 segapsg rf5c164 native_audio_effect'),
  synth: ids('ym2612 nuked_opn2 segapsg nesapu pwm32x ym2203 ym2608 rf5c164 native_audio_effect'),
  // Remaining CLI assets are discovered from static imports by build_cli.mjs.
  cli: ids('nesapu pwm32x'),
});

function profileIds(profile) {
  const selected = runtimeArtifactProfiles[profile];
  if (!selected) throw new Error(`Unknown runtime artifact profile: ${profile}`);
  return selected;
}

export async function checkRuntimeArtifactProfile(profile, {root = repositoryRoot} = {}) {
  return checkRuntimeArtifacts({root, ids: profileIds(profile), mirrors: true});
}

export async function copyRuntimeArtifactProfile(profile, stage, {root = repositoryRoot, layout = 'js'} = {}) {
  if (!['js', 'flat'].includes(layout)) throw new Error(`Unknown runtime layout: ${layout}`);
  const selected = profileIds(profile);
  // Packaging is a read-only consumer. A stale public copy must be explicitly
  // synchronized and checked by calibration before distribution, never repaired here.
  await checkRuntimeArtifactProfile(profile, {root});
  const files = await listRuntimeArtifactFiles({root, ids: selected});
  const jsDirectory = layout === 'flat' ? stage : join(stage, 'js');
  if (selected.includes('dx7')) {
    await mkdir(jsDirectory, {recursive: true});
    // Keep vendor source, notices and relative module layout; its generated
    // binary is copied below from tetorica_src/runtime/generated rather than this source package.
    const source = join(root, 'tetorica_src/runtime/msfa_dx7');
    await cp(source, join(jsDirectory, 'msfa_dx7'), {
      recursive: true,
      filter: path => path !== join(source, 'wasm/msfa.wasm'),
    });
  }
  let copied = 0;
  for (const file of files) {
    // This describes the canonical development tree, not an application subset.
    if (file.path === 'runtime-artifacts.json') continue;
    // Only Playground historically ships the generic compiler receipt. The
    // PS1 authenticated build receipt stays with every PS1 distribution.
    if (file.path === 'build-info.json' && profile !== 'playground') continue;
    const destination = file.id === 'native_audio_effect'
      ? join(jsDirectory, 'native_audio_effect.wasm')
      : file.id === 'dx7'
        ? join(jsDirectory, 'msfa_dx7/wasm/msfa.wasm')
        : join(stage, 'generated', file.path);
    await mkdir(dirname(destination), {recursive: true});
    await cp(file.source, destination);
    copied++;
  }
  return {profile, ids: [...selected], files: copied};
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const [profile, action, stage, layout] = process.argv.slice(2);
  if (action === '--check' && !stage) await checkRuntimeArtifactProfile(profile);
  else if (action === '--copy' && stage) await copyRuntimeArtifactProfile(profile, resolve(stage), {layout: layout ?? 'js'});
  else throw new Error('Usage: node scripts/runtime_artifact_profiles.mjs <full|playground|analyzer|synth|cli> <--check|--copy STAGE [js|flat]>');
}
